              outputRetainedBytes += encodedBytes;
            } else {
              outputTruncated = true;
            }
            updateSnapshotUnlocked(paths, current => ({
              ...current,
              generation: current.generation + 1,
              outputSequence,
              outputRetainedBytes,
              outputTruncated,
              lastProviderProgressAt: progressAt,
            }));
          });
        },
      },
    );

    if (supervisorFailure) throw supervisorFailure;

    // The child close fence wins only when the deadline callback arrived AFTER
    // the provider close. An `aborted` result proves the opposite ordering: the
    // managed deadline/cancel reached a still-live provider and caused its
    // close. That must remain a timed_out terminal rather than falling through
    // to the ordinary nonzero-exit failure path. Injected legacy runners have
    // no close proof, so their deadline behavior remains fail-closed.
    const deadlineAbortedLiveProvider = deadlineTriggered && result.terminalReason === 'aborted';
    if (result.timedOut || deadlineAbortedLiveProvider || (deadlineTriggered && result.closeObserved !== true)) {
      // runHostRun is capped to the remaining managed deadline. When its total
      // timer and this worker's deadline timer become runnable together, event
      // loop ordering must not downgrade an expired managed deadline into a
      // provider-local timeout.
      const managedDeadlineReached = deadlineTriggered || now() >= Date.parse(spec.deadlineAt);
      return writeTerminal(
        paths,
        'timed_out',
        managedDeadlineReached ? 'absolute_deadline_exceeded' : result.timeoutKind ?? 'provider_total_timeout',
        result.replacementSafe,
        result,
        now(),
      );
    }
    const postResultCancellation = readCancelRequest(paths);
    const closeFencedDeadline = result.closeObserved === true && deadlineTriggered && !deadlineAbortedLiveProvider;
    if (cancelTriggered || (postResultCancellation
      && !(closeFencedDeadline && postResultCancellation.reason === 'absolute_deadline_exceeded'))) {
      const terminal = classifyManagedHostRunCancellation(postResultCancellation?.reason ?? 'cancelled');
      return writeTerminal(paths, terminal.state, terminal.reason, result.replacementSafe, result, now());
    }
    if (result.blocked || result.exitCode !== 0) {
      const classifiedReason = result.failureKind && !['none', 'unknown'].includes(result.failureKind)
        ? result.failureKind
        : null;
      return writeTerminal(
        paths,
        'failed',
        result.refusalReason ?? classifiedReason ?? result.terminalReason ?? `provider_exit_${result.exitCode}`,
        result.replacementSafe,
        result,
        now(),
      );
    }
    if (spec.profile === 'managed_reviewer') {
      const existingProposal = readValidManagedReviewEvidenceProposal(spec.root, spec.runId, spec);
      deps.afterManagedReviewProposalPreRead?.({
        root: spec.root,
        runId: spec.runId,
        hasValidProposal: existingProposal !== null,
      });
      // Older adapters may already have submitted one descriptor-attested,
      // immutable proposal before their ordinary final prose is emitted. That
      // proposal is the compatibility authority; only runs without it use the
      // canonical final-result lane.
      if (!existingProposal) {
        try {
          const proposal = parseManagedReviewFinalProposal(result);
          writeManagedReviewEvidenceProposal({
            root: spec.root,
            runId: spec.runId,
            proposal,
            environment: {
              LATTICE_MANAGED_HOST_RUN_ID: spec.runId,
              LATTICE_MANAGED_REVIEW_PROPOSAL_CAPABILITY: capability,
              LATTICE_AGENT: spec.agentType,
            },
          });
        } catch (error) {
          // A compatibility callback can win after the first read but before
          // the final-result writer takes the immutable-file fence. Its valid
          // proposal is the authority; malformed or absent competitors still
          // leave this final result fail-closed.
          if (readValidManagedReviewEvidenceProposal(spec.root, spec.runId, spec)) {
            return writeTerminal(paths, 'completed', 'provider_completed', result.replacementSafe, result, now());
          }
          return writeTerminal(
            paths,
            'failed',
            `managed_review_final_result_invalid:${error instanceof Error ? error.message : String(error)}`,
            result.replacementSafe,
            result,
            now(),
          );
        }
      }
      if (!readValidManagedReviewEvidenceProposal(spec.root, spec.runId, spec)) {
        return writeTerminal(paths, 'failed', 'managed_review_final_result_missing', result.replacementSafe, result, now());
      }
    }
    return writeTerminal(paths, 'completed', 'provider_completed', result.replacementSafe, result, now());
  } catch (error) {
    const failedSnapshot = readManagedHostRunSnapshot(paths);
    const cleanup = result?.processCleanup
      ?? (failedSnapshot.providerIdentity
        ? await reapManagedHostRunProviderProcess(failedSnapshot.providerIdentity)
        : failedSnapshot.providerLaunchState === 'pending' || failedSnapshot.providerLaunchState === 'revoked'
          ? REAPED_WITHOUT_SIGNAL
          : AMBIGUOUS_PROCESS_CLEANUP);
    const replacementSafe = result?.replacementSafe ?? cleanupIsReplacementSafe(cleanup);
    const capturedSupervisorFailure = supervisorFailure as Error | null;
    if (capturedSupervisorFailure) {
      return writeTerminal(paths, 'failed', `worker_error:${capturedSupervisorFailure.message}`, replacementSafe, result, now(), cleanup);
    }
    if (deadlineTriggered) {
      return writeTerminal(paths, 'timed_out', 'absolute_deadline_exceeded', replacementSafe, result, now(), cleanup);
    }
    const caughtCancellation = readCancelRequest(paths);
    if (cancelTriggered || caughtCancellation) {
      const terminal = classifyManagedHostRunCancellation(caughtCancellation?.reason ?? 'cancelled');
      return writeTerminal(paths, terminal.state, terminal.reason, replacementSafe, result, now(), cleanup);
    }
    return writeTerminal(paths, 'failed', `worker_error:${error instanceof Error ? error.message : String(error)}`, replacementSafe, result, now(), cleanup);
  } finally {
    clearInterval(heartbeat);
    clearInterval(cancelPoll);
    clearTimeout(deadlineTimer);
  }
}

function ensureCancelRequest(
  paths: ManagedHostRunPaths,
  runId: string,
  reason: string,
  now: number,
): ManagedHostRunCancelRequest {
  assertArtifactRunId(paths, 'cancel request', runId);
  const existing = readCancelRequest(paths);
  if (existing) return existing;
  const request: ManagedHostRunCancelRequest = {
    schemaVersion: MANAGED_HOST_RUN_SCHEMA_VERSION,
    runId,
    requestedAt: new Date(now).toISOString(),
    reason: reason.trim() || 'cancelled',
  };
  if (!writeExclusive(paths.cancelRequest, request)) return readCancelRequest(paths)!;
  appendEvent(paths, {
    schemaVersion: MANAGED_HOST_RUN_SCHEMA_VERSION,
    runId,
    at: request.requestedAt,
    type: 'cancel_requested',
    detail: { reason: request.reason },
  });
  return request;
}

export interface ManagedHostRunProcessGroupRow {
  pid: number;
  pgid: number;
  sessionId: number;
  start: string;
}

export interface ManagedHostRunProcessGroupOps {
  rows(pgid: number): ManagedHostRunProcessGroupRow[] | null;
  signal(pgid: number, signal: 'SIGTERM' | 'SIGKILL'): void;
  wait(ms: number): Promise<void>;
}

function processGroupRows(pgid: number): ManagedHostRunProcessGroupRow[] | null {
  if (process.platform === 'win32') return null;
  try {
    const output = execFileSync('ps', ['-axo', 'pid=,pgid=,sess=,lstart='], {
      encoding: 'utf8',
      timeout: 1_000,
      stdio: ['ignore', 'pipe', 'ignore'],
    });
    return output
      .split('\n')
      .map(line => /^\s*(\d+)\s+(\d+)\s+(\d+)\s+(.+?)\s*$/.exec(line))
      .filter((match): match is RegExpExecArray => match !== null)
      .map(match => ({ pid: Number(match[1]), pgid: Number(match[2]), sessionId: Number(match[3]), start: match[4]! }))
      .filter(row => row.pgid === pgid);
  } catch {
    return null;
  }
}

const DEFAULT_PROCESS_GROUP_OPS: ManagedHostRunProcessGroupOps = {
  rows: processGroupRows,
  signal: (pgid, signal) => process.kill(-pgid, signal),
 * provider progress as separate facts: neither a stale heartbeat nor output
 * silence is promoted to a terminal outcome by this scan.
 */
export function scanManagedHostRunRuntime(
  root: string,
  options: { now?: number; retentionMs?: number } = {},
): ManagedHostRunRuntimeScan {
  const runtimeRoot = managedHostRunsRoot(root);
  const now = options.now ?? Date.now();
  const retentionMs = boundedPositiveMs(
    options.retentionMs,
    MANAGED_HOST_RUN_TERMINAL_RETENTION_MS,
    Number.MAX_SAFE_INTEGER,
  );
  const runs: ManagedHostRunRuntimeDiagnostic[] = [];
  if (existsSync(runtimeRoot)) {
    for (const entry of readdirSync(runtimeRoot, { withFileTypes: true })) {
      if (!entry.isDirectory()) continue;
      const runId = entry.name;
      try {
        assertRunId(runId);
        const paths = pathsFor(root, runId);
        const run = projectionFor(paths);
        const terminalAt = run.terminal?.terminalAt ?? null;
        const terminalAtMs = terminalAt ? Date.parse(terminalAt) : Number.NaN;
        const retentionEligibleAt = Number.isFinite(terminalAtMs)
          ? new Date(terminalAtMs + retentionMs).toISOString()
          : null;
        const hasUnconsumedOneShotInputs = existsSync(paths.capability)
          || existsSync(paths.prompt)
          || existsSync(paths.environment);
        const workerLiveness = run.terminal
          ? 'not-applicable'
          : run.workerPid === null
            ? 'not-started'
            : pidAlive(run.workerPid)
              ? 'alive'
              : 'dead';
        runs.push({
          runId,
          state: run.state,
          workerLiveness,
          workerHeartbeatAt: run.workerHeartbeatAt,
          workerHeartbeatAgeMs: timestampAgeMs(run.workerHeartbeatAt, now),
          providerProgressMode: run.providerProgressMode,
          lastProviderProgressAt: run.lastProviderProgressAt,
          providerProgressAgeMs: timestampAgeMs(run.lastProviderProgressAt, now),
          deadlineAt: run.deadlineAt,
          deadlineExpired: now >= Date.parse(run.deadlineAt),
          cancelRequestedAt: run.cancelRequestedAt,
          replacementSafe: run.replacementSafe,
          residualProcessGroup: run.terminal?.processCleanup?.residualProcessGroup ?? null,
          terminalAt,
          terminalReason: run.terminal?.reason ?? null,
          retentionEligibleAt,
          retentionExpired: !!retentionEligibleAt && now >= Date.parse(retentionEligibleAt),
          hasUnconsumedOneShotInputs,
          error: null,
        });
      } catch (error) {
        const dir = join(runtimeRoot, runId);
        runs.push({
          runId,
          state: 'corrupt',
          workerLiveness: 'unknown',
          workerHeartbeatAt: null,
          workerHeartbeatAgeMs: null,
          providerProgressMode: 'unknown',
          lastProviderProgressAt: null,
          providerProgressAgeMs: null,
          deadlineAt: null,
          deadlineExpired: null,
          cancelRequestedAt: null,
          replacementSafe: null,
          residualProcessGroup: null,
          terminalAt: null,
          terminalReason: null,
          retentionEligibleAt: null,
          retentionExpired: false,
          hasUnconsumedOneShotInputs: existsSync(join(dir, 'input.cap'))
            || existsSync(join(dir, 'input.prompt'))
            || existsSync(join(dir, 'input.env.json')),
          error: error instanceof Error ? error.message : String(error),
        });
      }
    }
  }
  runs.sort((left, right) => left.runId.localeCompare(right.runId));
  return {
    root: runtimeRoot,
    retentionMs,
    active: runs.filter(run => !['completed', 'failed', 'cancelled', 'timed_out', 'corrupt'].includes(run.state)).length,
    terminal: runs.filter(run => ['completed', 'failed', 'cancelled', 'timed_out'].includes(run.state)).length,
    corrupt: runs.filter(run => run.state === 'corrupt').length,
    eligibleForGc: runs.filter(run => run.retentionExpired && !run.hasUnconsumedOneShotInputs).length,
    runs,
  };
}

/**
 * B-137a:F-135 — a receipt archive can replace the live runtime only when it
 * can re-verify already-imported evidence after deletion: sealed receipt,
 * binding projection, proposal body, evidence-binding body, and seal
 * schemaVersion/runId/bindingDigest. Null proposal/binding is complete only
 * when the live receipt/digest also says those artifacts were absent.
 */
function isCompleteValidReceiptArchive(
  archive: ManagedHostRunReceiptArchive,
  expected: {
    runId: string;
    receiptId: string;
    evidenceProposalDigest: string | null;
    evidenceBindingDigest: string | null;
  },
): boolean {
  if (archive.schemaVersion !== 'lattice.managed_host_run_receipt_archive.v1') return false;
  if (archive.runId !== expected.runId) return false;
  const receipt = archive.receipt;
  if (!receipt || receipt.runId !== expected.runId || receipt.receiptId !== expected.receiptId) return false;
  const { receiptId, ...payload } = receipt;
  if (receiptId !== sha256(canonicalJson(payload))) return false;
  if (receipt.evidenceProposalDigest !== expected.evidenceProposalDigest) return false;
  if (!archive.binding || archive.binding.runId !== expected.runId) return false;

  const proposalText = archive.evidenceProposalText ?? null;
  if (expected.evidenceProposalDigest === null) {
    if (proposalText !== null) return false;
  } else if (proposalText === null || sha256(proposalText) !== expected.evidenceProposalDigest) {
    return false;
  }

  const bindingText = archive.evidenceBindingText ?? null;
  const sealText = archive.evidenceBindingSealText ?? null;
  if (expected.evidenceBindingDigest === null) {
    if (bindingText !== null || sealText !== null) return false;
    if ((archive.evidenceBindingDigest ?? null) !== null) return false;
  } else if (
    bindingText === null
    || sealText === null
    || archive.evidenceBindingDigest !== expected.evidenceBindingDigest
    || sha256(bindingText) !== expected.evidenceBindingDigest
    || !importSealMatchesLiveContract(expected.runId, bindingText, sealText)
  ) {
    return false;
  }
  return true;
}

function persistManagedHostRunReceiptArchive(
  archivePath: string,
  archive: ManagedHostRunReceiptArchive,
  runId: string,
): void {
  const expected = {
    runId,
    receiptId: archive.receipt.receiptId,
    evidenceProposalDigest: archive.receipt.evidenceProposalDigest,
    evidenceBindingDigest: archive.evidenceBindingDigest,
  };
  if (!isCompleteValidReceiptArchive(archive, expected)) {
    throw new Error(`managed host run ${runId}: live artifacts cannot form a complete receipt archive`);
  }
  if (writeExclusive(archivePath, archive)) return;
  let existing: ManagedHostRunReceiptArchive;
  try {
    existing = readJson<ManagedHostRunReceiptArchive>(archivePath);
  } catch (error) {
    const cause = error instanceof Error ? error.message : String(error);
    throw new Error(`managed host run ${runId}: existing archived receipt is corrupt (${cause})`);
  }
  if (existing.receipt?.receiptId !== archive.receipt.receiptId) {
    throw new Error(`managed host run ${runId}: existing archived receipt does not match terminal receipt`);
  }
  if (isCompleteValidReceiptArchive(existing, expected)) return;
  // ReceiptId-only leftovers (crash or pre-F-127) must not keep an incomplete
  // archive and then delete the only complete live artifacts.
  atomicWrite(archivePath, archive);
}

/**
 * Explicit bounded GC used by doctor --repair. Active/corrupt runs and any
 * directory still carrying one-shot secrets are retained fail-closed.
 */
export function pruneExpiredManagedHostRuns(
  root: string,
  options: { now?: number; retentionMs?: number } = {},
): ManagedHostRunGcResult {
  const scan = scanManagedHostRunRuntime(root, options);
  const result: ManagedHostRunGcResult = { removed: [], archivedReceipts: [], retained: [], failed: [] };
  for (const run of scan.runs) {
    if (run.state === 'corrupt') {
      result.retained.push({ runId: run.runId, reason: 'corrupt_runtime_retained_for_manual_review' });
      continue;
    }
    if (!['completed', 'failed', 'cancelled', 'timed_out'].includes(run.state)) {
      result.retained.push({ runId: run.runId, reason: 'active_run_protected' });
      continue;
    }
    if (run.hasUnconsumedOneShotInputs) {
      result.retained.push({ runId: run.runId, reason: 'one_shot_inputs_present_retained' });
      continue;
    }
    if (!run.retentionExpired) {
      result.retained.push({ runId: run.runId, reason: 'within_terminal_retention_window' });
      continue;
    }
    try {
      const paths = pathsFor(root, run.runId);
      // The same verified run-id binding is used for expiry GC, so terminal
      // retention cannot reclaim host-runs/<id> while retaining a plaintext
      // Claude prompt sibling outside that directory.
      cleanupManagedClaudePromptForTerminal(paths);
      const spec = readManagedHostRunSpec(paths).value;
      const archivePath = managedHostRunReceiptArchivePath(root, run.runId);
      mkdirSync(managedHostRunReceiptsRoot(root), { recursive: true, mode: 0o700 });
      const archive: ManagedHostRunReceiptArchive = {
        schemaVersion: 'lattice.managed_host_run_receipt_archive.v1',
        runId: run.runId,
        archivedAt: run.terminalAt ?? new Date(options.now ?? Date.now()).toISOString(),
        receipt: managedHostRunReceipt(root, run.runId),
        evidenceBindingDigest: digestFile(paths.evidenceBinding),
        // B-137a:F-127 — capture the binding BEFORE removeManagedHostRunRuntime
        // deletes spec.json/owner.json, otherwise verifyManagedReviewEvidence
        // can never reconstruct it and every imported receipt for this run turns
        // into managed_receipt_invalid (absent from SUPERSEDED_PASS_ISSUE_CODES,
        // so it hard-blocks REVIEW->TEST -- the F-100 deadlock mechanism).
        binding: readManagedHostRunBinding(root, run.runId),
        // B-137a:F-127 — capture the RAW BYTES before removeManagedHostRunRuntime
        // deletes them. The sealed evidenceProposalDigest is sha256 over the file
        // text, so storing a re-serialized object would not re-digest identically.
        evidenceProposalText: existsSync(paths.evidenceProposal)
          ? readFileSync(paths.evidenceProposal, 'utf8')
          : null,
        evidenceBindingText: existsSync(paths.evidenceBinding)
          ? readFileSync(paths.evidenceBinding, 'utf8')
          : null,
        evidenceBindingSealText: existsSync(paths.evidenceBindingSeal)
          ? readFileSync(paths.evidenceBindingSeal, 'utf8')
          : null,
      };
      persistManagedHostRunReceiptArchive(archivePath, archive, run.runId);
      if (spec.profile === 'cross_host_review_codex') {
        cleanupManagedCrossHostReviewWorktree(spec.root, spec.cwd);
      }
      removeManagedHostRunRuntime(root, run.runId);
      result.removed.push(run.runId);
      result.archivedReceipts.push(run.runId);
    } catch (error) {
      result.failed.push({ runId: run.runId, error: error instanceof Error ? error.message : String(error) });
    }
  }
  return result;
}

/** Used only by bounded repair/cleanup code; never follows caller-provided paths. */
export function removeManagedHostRunRuntime(root: string, runId: string): void {
  rmSync(managedHostRunDirectory(root, runId), { recursive: true, force: true });
}
/**
 * Canonical, ledger-independent provider-process capacity registry.
 *
 * Admission is an atomic exclusive create of one of a fixed set of numbered
 * slots. Usage accounting may be disabled; this registry never is. A recorded
 * live pid is never reclaimed because of age alone, and release is guarded by
 * the acquire-minted ownership token.
 */

import { randomUUID } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import {
  mkdirSync,
  readdirSync,
  readFileSync,
  statSync,
  unlinkSync,
  renameSync,
  writeFileSync,
} from 'node:fs';
import { hostname } from 'node:os';
import { dirname, join } from 'node:path';
import {
  acquireMkdirLock,
  type ExistingMkdirLockSnapshot,
  type ExistingMkdirLockState,
} from './mkdir-lock.js';
import { resolveCanonicalRuntimeProjectRoot } from './runtime-artifact-registry.js';

const PROVIDER_PROCESS_SLOTS_RELATIVE = join('.lattice', 'runtime', 'provider-process-slots');
export const PROVIDER_PROCESS_MAX_CONCURRENT_DEFAULT = 4;
export const PROVIDER_PROCESS_SLOT_STALE_MS_DEFAULT = 6 * 60 * 60 * 1000;

export interface ProviderProcessLiveDescriptor {
  pid: number;
  startedAt: string;
  host: string;
  storyId: string | null;
  agentType: string;
}

export interface ProviderProcessSlotMeta extends ProviderProcessLiveDescriptor {}

export interface ProviderProcessSlotFileMeta extends ProviderProcessSlotMeta {
  token: string;
  providerPid?: number;
  providerPgid?: number;
  providerSpawnedAt?: string;
  providerStartFingerprint?: string;
  providerProcessGroupIsolated?: boolean;
}

export interface AcquiredProviderProcessSlot {
  file: string;
  token: string;
}

export interface ProviderRegistryLockTiming {
  deadlineMs?: number;
  staleMs?: number;
  pollMs?: number;
}

export interface ProviderRegistryMutationOps {
  unlink(file: string): void;
}

const DEFAULT_PROVIDER_REGISTRY_MUTATION_OPS: ProviderRegistryMutationOps = {
  unlink: unlinkSync,
};

type SlotOccupant =
  | { state: 'valid'; pid: number; token: string | null; meta: Record<string, unknown> }
  | { state: 'corrupt'; identity: string }
  | { state: 'missing' };

function corruptSlotIdentity(file: string, raw: string): string {
  try {
    const stat = statSync(file);
    return `${stat.dev}:${stat.ino}:${stat.size}:${stat.mtimeMs}:${raw}`;
  } catch (error) {
    return `unstatable:${(error as NodeJS.ErrnoException).code ?? 'unknown'}:${raw}`;
  }
}

function ownString(value: Record<string, unknown>, key: string): string | null {
  if (!Object.prototype.hasOwnProperty.call(value, key)) return null;
  return typeof value[key] === 'string' ? value[key] as string : null;
}

function ownNumber(value: Record<string, unknown>, key: string): number | null {
  if (!Object.prototype.hasOwnProperty.call(value, key)) return null;
  return typeof value[key] === 'number' && Number.isInteger(value[key]) ? value[key] as number : null;
}

function readSlotOccupant(file: string): SlotOccupant {
  let raw: string;
  try {
    raw = readFileSync(file, 'utf8');
  } catch (error) {
    return (error as NodeJS.ErrnoException).code === 'ENOENT'
      ? { state: 'missing' }
      : { state: 'corrupt', identity: corruptSlotIdentity(file, '') };
  }
  try {
    const parsed = JSON.parse(raw) as unknown;
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
      return { state: 'corrupt', identity: corruptSlotIdentity(file, raw) };
    }
    const meta = parsed as Record<string, unknown>;
    const pid = ownNumber(meta, 'pid');
    if (pid === null) return { state: 'corrupt', identity: corruptSlotIdentity(file, raw) };
    return { state: 'valid', pid, token: ownString(meta, 'token'), meta };
  } catch {
    return { state: 'corrupt', identity: corruptSlotIdentity(file, raw) };
  }
}

function sameSlotOccupant(left: SlotOccupant, right: SlotOccupant): boolean {
  if (left.state !== right.state) return false;
  if (left.state === 'valid' && right.state === 'valid') {
    return left.pid === right.pid && left.token === right.token;
  }
  if (left.state === 'corrupt' && right.state === 'corrupt') {
    return left.identity === right.identity;
  }
  return true;
}

function pidAlive(pid: number): boolean {
  if (!Number.isInteger(pid) || pid <= 0) return false;
  try {
    process.kill(pid, 0);
    return true;
  } catch (error) {
    return (error as NodeJS.ErrnoException).code === 'EPERM';
  }
}

function processGroupAlive(pgid: number): boolean {
  if (!Number.isInteger(pgid) || pgid <= 1 || process.platform === 'win32') return false;
  try {
    process.kill(-pgid, 0);
    return true;
  } catch (error) {
    return (error as NodeJS.ErrnoException).code === 'EPERM';
  }
}

function slotReclaimable(occupant: SlotOccupant, file: string, now: number, staleMs: number): boolean {
  if (occupant.state === 'missing') return true;
  if (occupant.state === 'valid') {
    const isolated = occupant.meta.providerProcessGroupIsolated === true;
    const providerPgid = ownNumber(occupant.meta, 'providerPgid');
    // Once the admission has transferred to an isolated provider group, the
    // group—not the supervising worker—is the capacity owner. A crashed worker
    // may leave children alive, so reclaim only after the exact PGID disappears.
    if (isolated && providerPgid !== null && processGroupAlive(providerPgid)) return false;
    return !pidAlive(occupant.pid);
  }
  try {
    const ageMs = now - statSync(file).mtimeMs;
    return !Number.isFinite(ageMs) || ageMs > staleMs;
  } catch {
    // Fail closed: an existing slot we cannot stat still occupies capacity.
    return false;
  }
}

export function providerProcessSlotsDir(root: string): string {
  return join(resolveCanonicalRuntimeProjectRoot(root), PROVIDER_PROCESS_SLOTS_RELATIVE);
}

export function resolveProviderProcessMaxConcurrent(env: NodeJS.ProcessEnv): number {
  const raw = env.LATTICE_HOST_RUN_MAX_CONCURRENT;
  if (typeof raw !== 'string' || raw.trim().length === 0) return PROVIDER_PROCESS_MAX_CONCURRENT_DEFAULT;
  const value = Number(raw.trim());
  return Number.isFinite(value) && Number.isInteger(value) && value > 0
    ? value
    : PROVIDER_PROCESS_MAX_CONCURRENT_DEFAULT;
}

export function resolveProviderProcessSlotStaleMs(env: NodeJS.ProcessEnv): number {
  const raw = env.LATTICE_HOST_RUN_SLOT_STALE_MS;
  if (typeof raw !== 'string' || raw.trim().length === 0) return PROVIDER_PROCESS_SLOT_STALE_MS_DEFAULT;
  const value = Number(raw.trim());
  return Number.isFinite(value) && value > 0 ? value : PROVIDER_PROCESS_SLOT_STALE_MS_DEFAULT;
}

export function writeProviderProcessSlotExclusive(
  file: string,
  meta: ProviderProcessSlotFileMeta,
): boolean {
  try {
    writeFileSync(file, JSON.stringify(meta), { encoding: 'utf8', flag: 'wx', mode: 0o600 });
    return true;
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'EEXIST') return false;
    throw error;
  }
}

function scanLiveProviderProcessSlotsUnlocked(
  dir: string,
  now: number,
  staleMs: number,
): ProviderProcessLiveDescriptor[] {
  let entries: string[];
  try {
    entries = readdirSync(dir);
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return [];
    const code = (error as NodeJS.ErrnoException).code ?? 'unknown';
    const detail = error instanceof Error ? error.message : String(error);
    throw new Error(`provider-process-registry slots directory unreadable (${code}): ${detail}`);
  }
  const live: ProviderProcessLiveDescriptor[] = [];
  for (const name of entries) {
    if (!name.endsWith('.json')) continue;
    const file = join(dir, name);
    const occupant = readSlotOccupant(file);
    if (slotReclaimable(occupant, file, now, staleMs)) {
      if (occupant.state !== 'missing' && sameSlotOccupant(readSlotOccupant(file), occupant)) {
        try { unlinkSync(file); } catch { /* racing reclaim is benign */ }
      }
      continue;
    }
    if (occupant.state !== 'valid') continue;
    live.push({
      pid: occupant.pid,
      startedAt: ownString(occupant.meta, 'startedAt') ?? '',
      host: ownString(occupant.meta, 'host') ?? '',
      storyId: ownString(occupant.meta, 'storyId'),
      agentType: ownString(occupant.meta, 'agentType') ?? '',
    });
  }
  return live;
}

function currentProcessStartTimeMs(): number {
  return Math.floor(Date.now() - process.uptime() * 1_000);
}

function sameProcessStart(left: number | undefined, right: number | undefined): boolean {
  if (left === undefined || right === undefined) return true;
  return Math.abs(left - right) <= 2_000;
}

type ProviderRegistryLockPidState = 'active' | 'stale' | 'unknown';

export interface ProviderRegistryLockObservationOps {
  inspectPid?: (pid: number) => ProviderRegistryLockPidState;
  observeProcessStartTimeMs?: (pid: number) => number | undefined;
}

function inspectProviderRegistryLockPid(pid: number): ProviderRegistryLockPidState {
  try {
    process.kill(pid, 0);
    return 'active';
  } catch (error) {
    const code = (error as NodeJS.ErrnoException).code;
    if (code === 'ESRCH') return 'stale';
    if (code === 'EPERM') return 'active';
    return 'unknown';
  }
}

/**
 * Best-effort foreign-PID start identity, using ps elapsed time rather than a
 * signal or a provider launch. An unavailable platform/process observation is
 * deliberately not treated as proof of staleness.
 */
function observeProviderRegistryProcessStartTimeMs(pid: number): number | undefined {
  if (!Number.isInteger(pid) || pid <= 0 || process.platform === 'win32') return undefined;
  try {
    const raw = execFileSync('ps', ['-o', 'etimes=', '-p', String(pid)], {
      encoding: 'utf8',
      timeout: 1_000,
      stdio: ['ignore', 'pipe', 'ignore'],
    }).trim();
    const elapsedSeconds = Number(raw);
    return Number.isFinite(elapsedSeconds) && elapsedSeconds >= 0
      ? Math.floor(Date.now() - elapsedSeconds * 1_000)
      : undefined;
  } catch {
    return undefined;
  }
}

/**
 * Classify an existing registry lock with PID-reuse protection for every local
 * holder, not only this process. If a persisted start identity cannot be read
 * back safely after the PID was observed live, retain it as active rather than
 * falling through to mkdir-lock's age-based unknown-lock reclamation.
 */
export function classifyProviderRegistryLock(
  snapshot: ExistingMkdirLockSnapshot,
  ops: ProviderRegistryLockObservationOps = {},
): ExistingMkdirLockState {
  const holder = snapshot.holder;
  if (!holder || holder.hostname !== hostname()) return 'unknown';
  if (!Number.isInteger(holder.pid) || holder.pid <= 0) return 'unknown';
  const pidState = (ops.inspectPid ?? inspectProviderRegistryLockPid)(holder.pid);
  if (pidState !== 'active') return pidState;
  if (holder.processStartTimeMs !== undefined) {
    const observedStart = (ops.observeProcessStartTimeMs ?? observeProviderRegistryProcessStartTimeMs)(holder.pid);
    // The PID liveness probe succeeded. A missing start-time observation does
    // not demonstrate reuse, so fail closed: generic unknown-lock aging must
    // not reclaim a potentially live provider-registry lock.
    if (observedStart === undefined) return 'active';
    if (!sameProcessStart(holder.processStartTimeMs, observedStart)) return 'stale';
  }
  return 'active';
}

function withProviderRegistryLock<T>(
  dir: string,
  fn: () => T,
  timing: ProviderRegistryLockTiming = {},
): T {
  const lock = acquireMkdirLock(`${dir}.lock`, {
    label: 'provider-process-registry',
    deadlineMs: timing.deadlineMs ?? 30_000,
    staleMs: timing.staleMs ?? 10_000,
    pollMs: timing.pollMs ?? 10,
    requireHolderToken: true,
    classifyExistingLock: classifyProviderRegistryLock,
    holderInfo: {
      pid: process.pid,
      hostname: hostname(),
      command: 'provider-process-registry mutation',
      acquiredAt: new Date().toISOString(),
      lockId: randomUUID(),
      processStartTimeMs: currentProcessStartTimeMs(),
    },
  });
  try {
    return fn();
  } finally {
    lock.release();
  }
}

export function scanLiveProviderProcessSlots(
  dir: string,
  now: number,
  staleMs: number,
  lockTiming: ProviderRegistryLockTiming = {},
): ProviderProcessLiveDescriptor[] {
  return withProviderRegistryLock(dir, () => scanLiveProviderProcessSlotsUnlocked(dir, now, staleMs), lockTiming);
}

export function acquireProviderProcessSlot(
  dir: string,
  cap: number,
  staleMs: number,
  now: number,
  meta: ProviderProcessSlotMeta,
  lockTiming: ProviderRegistryLockTiming = {},
): AcquiredProviderProcessSlot | null {
  mkdirSync(dir, { recursive: true });
  const boundedCap = Number.isFinite(cap) && Number.isInteger(cap) && cap > 0
    ? cap
    : PROVIDER_PROCESS_MAX_CONCURRENT_DEFAULT;
  return withProviderRegistryLock(dir, () => {
    const live = scanLiveProviderProcessSlotsUnlocked(dir, now, staleMs);
    if (live.length >= boundedCap) return null;
    const token = randomUUID();
    const record: ProviderProcessSlotFileMeta = { ...meta, token };
    for (let index = 0; index < boundedCap; index += 1) {
      const file = join(dir, `slot-${index}.json`);
      if (writeProviderProcessSlotExclusive(file, record)) return { file, token };
      const judged = readSlotOccupant(file);
      if (!slotReclaimable(judged, file, now, staleMs)) continue;
      if (judged.state !== 'missing') {
        if (!sameSlotOccupant(readSlotOccupant(file), judged)) continue;
        try { unlinkSync(file); } catch { /* exclusive recreate decides the winner */ }
      }
      if (writeProviderProcessSlotExclusive(file, record)) return { file, token };
    }
    return null;
  }, lockTiming);
}

export function releaseProviderProcessSlot(
  file: string | null,
  token: string | null,
  lockTiming: ProviderRegistryLockTiming = {},
  mutationOps: ProviderRegistryMutationOps = DEFAULT_PROVIDER_REGISTRY_MUTATION_OPS,
): void {
  if (!file || !token) return;
  const dir = dirname(file);
  withProviderRegistryLock(dir, () => {
    const occupant = readSlotOccupant(file);
    if (occupant.state !== 'valid' || occupant.token !== token) return;
    mutationOps.unlink(file);
  }, lockTiming);
}

/**
 * B-137a F-119: BEST-EFFORT release for `finally` blocks.
 *
 * Two correct-but-opposed requirements meet here:
 *   1. A release failure must be OBSERVABLE, not a silent capacity leak --
 *      releaseProviderProcessSlot therefore throws, and a registry smoke pins
 *      that ("slot unlink mutation failure must be observable instead of
 *      silently leaking capacity").
 *   2. Every production release happens in a bare `finally` (host-run,
 *      autopilot-executor, codex-review-leaf, provider-process-admission), and
 *      a throw from `finally` REPLACES the in-flight exception -- hiding the
 *      real provider failure -- or turns a successful run into a hard error.
 *      host-run.ts's original releaseSlot wrapped its body in try/catch for
 *      exactly this reason; a refactor dropped that.
 *
 * Swallowing inside the primitive would satisfy (2) by destroying (1). So the
 * primitive keeps throwing and `finally` callers use this wrapper, which
 * reports the failure through onFailure instead of hijacking control flow.
 * Capacity is still reclaimable: pid-death detection and the orphan backstop
 * recover a leaked slot, whereas a masked exception is unrecoverable.
 */
export function releaseProviderProcessSlotBestEffort(
  file: string | null,
  token: string | null,
  onFailure: (error: unknown) => void = defaultReleaseFailureReporter,
  lockTiming: ProviderRegistryLockTiming = {},
  mutationOps: ProviderRegistryMutationOps = DEFAULT_PROVIDER_REGISTRY_MUTATION_OPS,
): void {
  try {
    releaseProviderProcessSlot(file, token, lockTiming, mutationOps);
  } catch (error) {
    // Never rethrow: this runs in finally. Reporting must not fail either.
    try {
      onFailure(error);
    } catch { /* a broken reporter must not mask the caller's exception */ }
  }
}

function defaultReleaseFailureReporter(error: unknown): void {
  const detail = error instanceof Error ? error.message : String(error);
  process.stderr.write(
    `⚠ provider process slot release failed (capacity is reclaimed by pid-death / orphan backstop): ${detail}\n`,
  );
}

export function transferProviderProcessSlotToProvider(
  file: string | null,
  token: string | null,
  identity: {
    pid: number;
    pgid: number | null;
    spawnedAt: string;
    startFingerprint: string | null;
    processGroupIsolated: boolean;
  },
  lockTiming: ProviderRegistryLockTiming = {},
): boolean {
  if (!file || !token) return false;
  if (
    !Number.isInteger(identity.pid) || identity.pid <= 0
    || !identity.processGroupIsolated
    || !Number.isInteger(identity.pgid) || (identity.pgid ?? 0) <= 0
  ) return false;
  const dir = dirname(file);
  return withProviderRegistryLock(dir, () => {
    const occupant = readSlotOccupant(file);
    if (occupant.state !== 'valid' || occupant.token !== token) return false;
    const next: ProviderProcessSlotFileMeta = {
      ...(occupant.meta as unknown as ProviderProcessSlotFileMeta),
      pid: identity.pid,
      providerPid: identity.pid,
      providerPgid: identity.pgid!,
      providerSpawnedAt: identity.spawnedAt,
      providerStartFingerprint: identity.startFingerprint ?? undefined,
      providerProcessGroupIsolated: true,
      token,
    };
    const temporary = `${file}.${token}.transfer`;
    writeFileSync(temporary, JSON.stringify(next), { encoding: 'utf8', flag: 'wx', mode: 0o600 });
    try {
      // Registry lock + exact token check makes this replacement ownership-safe.
      renameSync(temporary, file);
    } finally {
      try { unlinkSync(temporary); } catch { /* rename already consumed it */ }
    }
    return true;
  }, lockTiming);
}

export type ProviderExecutionSurfaceStatus =
  | 'managed'
  | 'admission_only'
  | 'adapter_only'
  | 'readiness_probe'
  | 'legacy_unmanaged';

export interface ProviderExecutionSurface {
  path: string;
  status: ProviderExecutionSurfaceStatus;
  admissionOwner: string | null;
  note: string;
}

/**
 * Conservative source classifier used by the contract smoke. Any production
 * file that imports a provider adapter, is itself an adapter, or combines a
 * child-process API with provider vocabulary must have an explicit inventory
 * row. False positives are classified, never silently excluded, so adding a
 * new direct provider spawn in a new file makes the contract fail closed.
 */
export function isProviderExecutionSurfaceCandidate(relativePath: string, source: string): boolean {
  if (!relativePath.endsWith('.ts')) return false;
  if (/(?:^|\/)(?:tasks|tests|generated)(?:\/|$)/.test(relativePath)) return false;
  if (relativePath === 'core/provider-process-registry.ts') return false;
  if (/^providers\/(?:codex-cli|claude-cli|gemini-cli)\.ts$/.test(relativePath)) return true;
  if (/providers\/(?:codex-cli|claude-cli|gemini-cli)\.js/.test(source)) return true;
  if (/\brunHostRun\s*\(/.test(source)) return true;
  // B-137a: strip documentation filename references before the provider-word
  // scan. The words are matched case-insensitively, so a prose citation of
  // "CLAUDE.md" (the project convention doc, referenced by many core modules)
  // read as a provider reference: any file that both used child_process for git
  // and cited that doc became an "unclassified provider execution surface".
  // scope-contract.ts tripped exactly this way on a comment citing the handler
  // convention -- a docs citation, not a provider workload. Several already
  // inventoried files (audit-scan, audit-trigger, rollout-check,
  // runtime-environment-checks) match for the same non-reason. Stripping only
  // "<provider>.md" filenames keeps every real provider reference intact,
  // including CLAUDE_CLI, claudeCli, 'claude' and providers/claude-cli.js.
  const withoutDocReferences = source.replace(/\b(?:codex|claude|agy|gemini|antigravity)\.md\b/gi, '');
  // B-137a: the provider word no longer requires a trailing \b. The old
  // /\bclaude\b/i missed identifier forms entirely -- `claudeCli`, `CLAUDE_CLI`,
  // `codexRunner` all failed to match, because \b does not break between two
  // word characters or before `_`. A file spawn

ing a provider through such an
  // identifier was therefore invisible to this tripwire (verified against the
  // pre-change regex). A leading boundary is kept so unrelated substrings do not
  // match, but the tail is now open so identifier and member forms are caught.
  return /node:child_process/.test(source)
    && /\b(?:codex|claude|agy|gemini|antigravity)/i.test(withoutDocReferences);
}

